check('quota recovers after a successful fresh state',()=>{withQuota({...freshQuota,error:'合成失败'});withQuota(freshQuota);assert.equal(el('quota-container').hidden,false);assert.equal(el('quota-last-known').hidden,true);assert.equal(el('quota-error-details').hidden,true);});
// Official account and conversation fixtures are synthetic and independent of local pricing.
const officialFixture=structuredClone(apiFixture);
officialFixture.quota=structuredClone(freshQuota);
officialFixture.officialCredits={status:'fresh',updatedAt:quotaNow,error:null,balance:'1234.567890',unlimited:false,hasCredits:true,usdEquivalent:'49.38271560',amountEquivalent:'49.38271560',trackingStartAt:quotaNow-600,trackingStartBalance:'1200.000000',netChange:'34.567890',history:[{observedAt:quotaNow-600,balance:'1200.000000'},{observedAt:quotaNow,balance:'1234.567890'}],note:'合成余额记录'};
officialFixture.conversations.push({id:'synthetic-thread-b',title:'合成任务 B',displayId:'TEST-B',activeTurnCount:0,turnCount:0,sourceType:'main',reading:{complete:true}});
officialFixture.officialUsage={'synthetic-thread-a':{status:'fresh',updatedAt:quotaNow,error:null,credits:'12.345678',usd:'0.493827',groups:[{model:'gpt-6-astra',reasoningEffort:'ultra',speed:'ultrafast',credits:'12.345678',tokens:{input:100,cachedInput:70,output:5,total:105}}],note:'合成整段对话记录'}};
function updateOfficial(value=officialFixture) { run("quotaRefreshError=null; quotaRefreshRequested=false; quotaRefreshRetryAt=0; officialUsageRequests.clear(); activeView='overview'; historyAll=false; selectedConversationId='synthetic-thread-a';"); update(value); }
