check('balance net change and dated history do not claim consumption',()=>{updateOfficial();assert.equal(el('official-net-change').textContent,'+34.56789 Credits');assert.match(el('official-tracking-start').textContent,/1,200 Credits/);assert.match(el('official-balance-history-list').children[0].textContent,/1,234.56789 Credits/);assert.match(document.querySelector('.official-tracking').textContent,/最新 − 起点/);assert.match(document.querySelector('.official-tracking').textContent,/净变化不等于实际消耗/);});
