check('official balance uses server USD fallback for custom units',()=>{const f=structuredClone(officialFixture);Object.assign(f.settings,{pricingMode:'custom',currencyCode:'CUSTOM',currencyName:'点',currencySymbol:'?',usdPerCredit:'900'});f.officialCredits.amountEquivalent=null;updateOfficial(f);assert.equal(el('official-equivalent').textContent,'≈US$49.38');assert.match(document.querySelector('.official-credits-card').textContent,/不受本地 Credit 单价设置影响/);});
